/**
 * Extract the human task/topic from a terminal's raw title.
 *
 * Each harness formats its terminal title differently:
 * - `claude`: `<spinner glyph> <topic>` (e.g. `✳ Terminal blind overlay`), or
 *   just `Claude Code` when idle — there's no topic then.
 * - `pi`: `<app title> - <session name> - <folder>` (e.g. `π - fix login - dashboard`).
 *   The session name is the middle segment; it may itself contain ` - `.
 * Returns `null` when no topic/session can be read.
 */

/** Strip a leading spinner/status glyph (and any other leading punctuation) plus spaces. */
function stripLeadingGlyph(title: string): string {
	return title.replace(/^[^\p{L}\p{N}]+/u, "").trim();
}

export function taskTitle(harness: string, rawTitle: string): string | null {
	if (typeof rawTitle !== "string") return null;
	const title = rawTitle.trim();
	if (!title) return null;

	switch (harness?.toLowerCase()) {
		case "pi": {
			const parts = stripLeadingGlyph(title).split(" - ");
			if (parts.length < 3) return null;
			const session = parts.slice(1, -1).join(" - ").trim();
			return session || null;
		}
		case "claude": {
			const topic = stripLeadingGlyph(title);
			if (!topic || topic === "Claude Code") return null;
			return topic;
		}
		default: {
			const topic = stripLeadingGlyph(title);
			return topic || null;
		}
	}
}

