/* FilesBox 가 열리고 닫힐 때 쓰는 Svelte 전이(프로젝트 면 · Overview Dock 공용).
   `flex` 는 형제 칸과 나누던 몫(flex-grow · min-height)이 0 까지 줄고 opacity 가 따라간다 — 터미널과 1:1 로 나누는 프로젝트 면.
   `fade` 는 opacity 만 — 칸 폭을 호스트가 직접 옮기는 Overview Dock(그리드 열 전이). 길이 · 곡선은 `--panel-fold-*`. */
import { cubicOut } from "svelte/easing";
import type { TransitionConfig } from "svelte/transition";

export type BoxFold = "flex" | "fade";

function foldMs(node: HTMLElement) {
	const raw = getComputedStyle(node).getPropertyValue("--panel-fold-duration").trim();
	const ms = raw.endsWith("ms") ? parseFloat(raw) : parseFloat(raw) * 1000;
	return Number.isFinite(ms) ? ms : 200;
}

export function boxFold(node: HTMLElement, { mode = "flex" }: { mode?: BoxFold } = {}): TransitionConfig {
	const base = { duration: foldMs(node), easing: cubicOut };
	if (mode === "fade") return { ...base, css: (t) => `opacity: ${t}` };
	const min = parseFloat(getComputedStyle(node).minHeight) || 0;
	return {
		...base,
		css: (t) => `flex-grow: ${t}; min-height: ${min * t}px; opacity: ${t}`,
	};
}

/**
 * The one state a worktree card or a sidebar project row shows, mirrored from the server's
 * `workflow::Kind` (`apps/server/src/workflow/mod.rs`), which also owns the priority between
 * Gate result, Lead review and task status. The client only draws it: `status-icon.svelte`.
 * Plan: `docs/plan/261001-unified-status-icon.md`.
 */
export type StatusKind =
	"idle" | "standby" | "queued" | "done" | "running" | "reviewing" | "asking" | "paused" | "failed";

/** Least to most urgent, the server's `Kind` order. */
const ORDER: StatusKind[] = ["idle", "standby", "queued", "done", "running", "reviewing", "asking", "paused", "failed"];

/** The more urgent of two kinds, as the server's `max` picks it. */
export function urgent(a: StatusKind, b: StatusKind): StatusKind {
	return ORDER.indexOf(a) >= ORDER.indexOf(b) ? a : b;
}

/** Accessible name and tooltip lead for each kind. */
export const STATUS_LABEL: Record<StatusKind, string> = {
	idle: "Idle",
	standby: "Terminal open",
	queued: "Queued",
	done: "Done",
	running: "Running",
	reviewing: "Lead reviewing",
	asking: "Waiting for your answer",
	paused: "Paused",
	failed: "Gate failed",
};

