			const parts = stripLeadingGlyph(title).split(" - ");
			if (parts.length < 3) return null;
			const session = parts.slice(1, -1).join(" - ").trim();
			return session || null;
		}
		case "claude": {
			const topic = stripLeadingGlyph(title);
			if (!topic || topic === "Claude Code") return null;
			return topic;
		}
		default: {
			const topic = stripLeadingGlyph(title);
			return topic || null;
		}
	}
}
